<template><div class="login"><div class="card"><div class="mark">PHM</div><h1>航天器健康管理平台</h1><p>请使用系统账号登录</p><el-form ref="formRef" :model="form" :rules="rules" @submit.prevent="submit"><el-form-item prop="username"><el-input v-model="form.username" size="large" placeholder="用户名" :prefix-icon="User"/></el-form-item><el-form-item prop="password"><el-input v-model="form.password" size="large" type="password" show-password placeholder="密码" :prefix-icon="Lock" @keyup.enter="submit"/></el-form-item><el-button type="primary" size="large" :loading="loading" native-type="submit">登录系统</el-button></el-form><small>查看者账号由管理员创建</small></div></div></template>
<script setup>import{reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{User,Lock}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';const route=useRoute(),router=useRouter(),formRef=ref(),loading=ref(false),form=reactive({username:'',password:''}),rules={username:[{required:true,message:'请输入用户名'}],password:[{required:true,message:'请输入密码'}]};const submit=async()=>{await formRef.value.validate();loading.value=true;try{const r=await fetch('/api/v1/auth/login/',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});const d=await r.json();if(!r.ok)throw Error(d.detail||'登录失败');localStorage.setItem('user',JSON.stringify(d));ElMessage.success('登录成功');router.replace(route.query.redirect||'/')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}};</script>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 20% 20%,#1b5480,#0b1d35 55%,#071427)}.card{width:390px;padding:40px;background:#fffffffa;border-radius:16px;box-shadow:0 24px 70px #0007;text-align:center}.mark{margin:auto;width:64px;height:64px;border-radius:16px;background:linear-gradient(135deg,#2788ef,#20bcae);display:grid;place-items:center;color:white;font-weight:800}.card h1{margin:20px 0 7px;color:#18304c}.card p{color:#8190a3;margin-bottom:28px}.el-button{width:100%}.card small{display:block;color:#9aa6b5;margin-top:22px}</style>
